import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    t = 1
    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        k = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        a.sort()
        if m <= k:
            print(0)
        else:
            sum_ = 0
            i = n
            devices = m
            soc = k
            while sum_ < m and devices > soc and i >= 1:
                i -= 1
                sum_ += a[i]
                devices -= a[i]
                soc -= 1
            if devices <= soc:
                print(n - i)
            else:
                i = n
                used = 0
                ss = 0
                j = 0
                while i >= 1 and ss < m:
                    i -= 1
                    if used >= k * j and j >= 1:
                        ss -= 1
                    ss += a[i]
                    used += 1
                    if used % k == 0 and used != 0:
                        j += 1
                if ss >= m:
                    print(used)
                else:
                    print(-1)

if __name__ == "__main__":
    solve()

