#include <bits/stdc++.h>
#define ll long long
#define ld long double
#define pb push_back
#define pi 3.14159265358979323846
const ll INF=1<<28;
#define MOD 1000000007
using namespace std;

ll POWER(ll base,ll expo)
{
    ll num=1;
    ll i=expo;
    while(i)
    {
        num=num*base;
        i--;
    }
    return num;
}
int main()
{
    ll t=1; //cin>>t;
    while(t--)
    {
       ll n,m,k; cin>>n>>m>>k;
       ll a[n];
       for(ll i=0;i<n;i++)
        cin>>a[i];
       sort(a,a+n);
       if(m<=k)cout<<0;
       else
       {
           ll sum=0,i=n,devices=m,soc=k;
           while(sum<m && devices>soc &&i>=1)
           {
               i--;
               sum+=a[i];
               devices-=a[i];
               soc--;
           }
           if(devices<=soc)cout<<n-i;
           else
           {
               ll i=n,used=0,ss=0,j=0;
               while(i>=1 && ss<m)
               {
                 i--;
                 if(used>=k*j && j>=1)
                    ss--;
                 ss+=a[i];
                 used++;
                 if(used%k==0 && used!=0)
                    j++;
               }
               if(ss>=m)cout<<used;
               else cout<<-1;
           }
       }
    }
    return 0;
}
